// Works with Claude (merged_response / content[]) and OpenAI output shapes
function getModelText(json) {
  if (typeof json?.merged_response === 'string') return json.merged_response;
  if (Array.isArray(json?.content)) {
    const t = json.content.filter(c => c.type === 'text').map(c => c.text).join('');
    if (t) return t;
  }
  if (json?.output?.[0]?.content?.[0]?.text) return json.output[0].content[0].text;
  if (typeof json?.output_text === 'string') return json.output_text;
  if (typeof json?.output === 'string') return json.output;
  if (typeof json?.text === 'string') return json.text;
  return '';
}

// Process EVERY alert email (several can arrive between runs)
const results = [];
const seen = new Set(); // skip the same job appearing in several alert emails

$input.all().forEach((item, index) => {
  const raw = getModelText(item.json);

  // Remove possible ```json ... ``` wrappers
  const cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  let data;
  try {
    data = JSON.parse(cleaned);
  } catch (e) {
    return; // skip an email the model couldn't parse
  }

  for (const job of (data.jobs || [])) {
    let cleanUrl = job.job_url || '';
    // Remove LinkedIn tracking parameters
    if (cleanUrl) cleanUrl = cleanUrl.split('?')[0];

    // LinkedIn job ID (or the URL / title+company) identifies a job
    const idMatch = cleanUrl.match(/jobs\/view\/(\d+)/);
    const key = idMatch ? idMatch[1] : (cleanUrl || `${job.job_title}|${job.company}`).toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);

    results.push({
      json: {
        job_title: job.job_title,
        company: job.company,
        location: job.location,
        job_url: cleanUrl
      },
      pairedItem: { item: index } // keeps the link to the source email
    });
  }
});

return results;

// ======================================================
// 1. ORIGINAL LINKEDIN JOB
// ======================================================

const job = $('filter Jobs').item.json;


// ======================================================
// 2. GET THE RESULT FROM "verifying from query"
// ======================================================

const verifierJson = $('verifying from query').item.json;

// Works with Claude (merged_response / content[]) and OpenAI output shapes
function getModelText(json) {
  if (typeof json?.merged_response === 'string') return json.merged_response;
  if (Array.isArray(json?.content)) {
    const t = json.content.filter(c => c.type === 'text').map(c => c.text).join('');
    if (t) return t;
  }
  if (json?.output?.[0]?.content?.[0]?.text) return json.output[0].content[0].text;
  if (typeof json?.output_text === 'string') return json.output_text;
  if (typeof json?.output === 'string') return json.output;
  if (typeof json?.text === 'string') return json.text;
  return '';
}

let verification = {
  posting_found: false,
  source_url: '',
  source_type: '',
  match_confidence: 'LOW',
  reason: ''
};

try {
  let raw = getModelText(verifierJson)
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
  const a = raw.indexOf('{'), b = raw.lastIndexOf('}');
  if (a !== -1 && b !== -1) raw = raw.slice(a, b + 1);
  verification = JSON.parse(raw);
} catch (error) {
  verification.reason = 'Verifier output could not be parsed.';
}


// ======================================================
// 3. GET CONTENT RETURNED BY TAVILY EXTRACT
//    (only when this item actually went through Extract)
// ======================================================

let pageText = '';

if (verification.posting_found === true) {
  if (Array.isArray($json.results) && $json.results.length > 0) {
    pageText = $json.results[0].raw_content || $json.results[0].content || '';
  }
  if (!pageText && typeof $json.raw_content === 'string') pageText = $json.raw_content;
  if (!pageText && typeof $json.content === 'string') pageText = $json.content;
  if (!pageText && typeof $json.extracted_content === 'string') pageText = $json.extracted_content;
}


// ======================================================
// 4. CLEAN THE EXTRACTED PAGE (HTML + markdown clutter)
// ======================================================

pageText = String(pageText)
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')        // markdown images
  .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')      // markdown links -> text
  .replace(/https?:\/\/\S+/g, ' ')              // bare URLs
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/\s+/g, ' ')
  .trim();


// ======================================================
// 5. CHECK THE PAGE REALLY IS ABOUT THIS JOB
// ======================================================

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9\u0590-\u05ff]+/g, ' ').trim();
const pageNorm = norm(pageText);
const titleWords = norm(job.job_title).split(' ').filter(w => w.length > 1);
const foundWords = titleWords.filter(w => pageNorm.includes(w));
const titleCoverage = titleWords.length ? foundWords.length / titleWords.length : 0;
const companyFirstWord = norm(job.company).split(' ')[0] || '';
const companyOnPage = companyFirstWord ? pageNorm.includes(companyFirstWord) : false;

// Start the text near where the job title first appears (skips site menus)
const firstWord = titleWords[0];
if (firstWord) {
  const idx = pageText.toLowerCase().indexOf(String(job.job_title).toLowerCase().slice(0, 20));
  if (idx > 300) pageText = pageText.slice(idx - 300);
}

// Prevent huge prompts / unnecessary cost
pageText = pageText.slice(0, 15000);

let rejectReason = '';
if (verification.posting_found !== true) rejectReason = 'No matching posting found by verifier.';
else if (/linkedin\.com/i.test(verification.source_url || '')) rejectReason = 'Source is LinkedIn (not allowed).';
else if (pageText.length < 800) rejectReason = 'Extracted page is too short to be a job description.';
else if (titleCoverage < 0.8) rejectReason = 'Job title not found on the extracted page.';
else if (!companyOnPage) rejectReason = 'Company name not found on the extracted page.';

const hasJobDescription = rejectReason === '';


// ======================================================
// 6. OUTPUT ONE STANDARD OBJECT FOR THE RATING MODEL
// ======================================================

return {
  json: {
    job_title: job.job_title || '',
    company: job.company || '',
    location: job.location || '',
    job_url: job.job_url || '',

    posting_found: hasJobDescription,
    source_url: hasJobDescription ? (verification.source_url || '') : '',
    source_type: hasJobDescription ? (verification.source_type || '') : '',
    match_confidence: verification.match_confidence || 'LOW',
    verification_reason: verification.reason || '',

    job_page_text: hasJobDescription ? pageText : '',
    has_job_description: hasJobDescription,

    // Debugging
    description_reject_reason: rejectReason,
    verifier_source_url: verification.source_url || '',
    title_coverage: Math.round(titleCoverage * 100) / 100,
    extracted_characters: hasJobDescription ? pageText.length : 0
  }
};

const ratingItems = $input.all();
const jobItems = $("prepare for job rating").all();

function getModelText(json) {
  if (typeof json?.merged_response === 'string') return json.merged_response;
  if (Array.isArray(json?.content)) {
    const t = json.content.filter(c => c.type === 'text').map(c => c.text).join('');
    if (t) return t;
  }
  if (json?.output?.[0]?.content?.[0]?.text) return json.output[0].content[0].text;
  if (typeof json?.output_text === 'string') return json.output_text;
  if (typeof json?.output === 'string') return json.output;
  if (typeof json?.text === 'string') return json.text;
  return '';
}

function parseModelJson(raw) {
  if (!raw) throw new Error("Rating model returned empty output");
  let cleaned = raw.trim()
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();
  const firstBrace = cleaned.indexOf("{");
  const lastBrace = cleaned.lastIndexOf("}");
  if (firstBrace !== -1 && lastBrace !== -1) cleaned = cleaned.slice(firstBrace, lastBrace + 1);
  cleaned = cleaned.replace(/,\s*}/g, "}").replace(/,\s*]/g, "]");
  return JSON.parse(cleaned);
}

return ratingItems.map((item, index) => {
  const job = jobItems[index]?.json || {};
  let rating = {};
  let parseError = false;
  let parseErrorMessage = "";
  const raw = getModelText(item.json);
  try {
    rating = parseModelJson(raw);
  } catch (error) {
    parseError = true;
    parseErrorMessage = error.message;
  }
  let fitScore = null;
  if (rating.fit_score !== undefined && rating.fit_score !== null && rating.fit_score !== "") {
    const parsedScore = Number(rating.fit_score);
    if (!Number.isNaN(parsedScore)) fitScore = parsedScore;
  }
  return {
    json: {
      job_title: rating.job_title || job.job_title || "",
      company: rating.company || job.company || "",
      location: rating.location || job.location || "",
      job_url: rating.job_url || job.job_url || "",
      fit_score: fitScore,
      recommendation: rating.recommendation || "UNKNOWN",
      confidence: rating.confidence || (job.has_job_description ? "HIGH" : "LOW"),
      role_seniority: rating.role_seniority || "UNKNOWN",
      required_years_experience: rating.required_years_experience || "UNKNOWN",
      reason: rating.reason || "",
      matching_skills: Array.isArray(rating.matching_skills) ? [...new Set(rating.matching_skills)] : [],
      missing_requirements: Array.isArray(rating.missing_requirements) ? [...new Set(rating.missing_requirements)] : [],
      mandatory_requirements_missing: Array.isArray(rating.mandatory_requirements_missing) ? [...new Set(rating.mandatory_requirements_missing)] : [],
      description_used: typeof rating.description_used === "boolean" ? rating.description_used : Boolean(job.has_job_description),
      has_job_description: Boolean(job.has_job_description),
      source_url: job.source_url || "",
      parse_error: parseError,
      parse_error_message: parseErrorMessage
    }
  };
});
